-- RCI-IMG-001 /xray
insert into public.prompts (
  external_ref, command, name, slug, mode, category_id, short_description, intention,
  use_cases, tags, expected_input, minimal_context, sufficient_context,
  required_variables, optional_variables, default_values, expected_output, output_format,
  quality_criteria, preserve_rules, avoid_rules, limitations, fallback_if_incomplete,
  input_type, output_type, risk_level, priority, status, show_image_card,
  thumbnail_spec, admin_notes, sort_order, published_at
)
select
  'RCI-IMG-001', '/xray', 'Vue X-ray', 'xray',
  'image'::public.app_mode, c.id, 'Transforme un objet en vue transparente montrant ses composants internes.', 'Rendre visible la structure interne plausible d''un objet.',
  ARRAY['/xray sur une photo produit pour obtenir vue x-ray sans changer l''identite visuelle.']::text[], ARRAY['xray', 'technique', 'produit']::text[],
  'Image jointe recommandee; texte de contexte optionnel', 'Objet, personne, lieu ou scene clairement visible, ou brief textuel assez precis.', 'Image exploitable + objectif compris + aucune contrainte contradictoire.',
