join public.ai_providers pr on pr.id = v.provider_id
where p.external_ref = 'RCI-IMG-057' and pr.key = 'chatgpt'
  and not exists (
    select 1 from public.prompt_versions existing
    where existing.variant_id = v.id and existing.version_label = 'v1.0'
  );
